61  // An adapter that wraps a hermes::Buffer in a llvh::MemoryBuffer
    62  class HermesLLVMMemoryBuffer : public llvh::MemoryBuffer {
    63   public:
    64    HermesLLVMMemoryBuffer(
    65        std::unique_ptr<hermes::Buffer> buffer,
    66        llvh::StringRef name,
    67        bool requiresNullTerminator = true)
    68        : name_(name), data_(std::move(buffer)) {
    69      auto start = reinterpret_cast<const char *>(data_->data());
    70      auto end = start + data_->size();
    71      init(start, end, requiresNullTerminator);
    72    }
    73    virtual BufferKind getBufferKind() const override {
    74      return llvh::MemoryBuffer::BufferKind::MemoryBuffer_Malloc;
    75    }
    76    virtual llvh::StringRef getBufferIdentifier() const override {
    77      return name_;
    78    }
    79
    80   private:
    81    std::string name_;
    82    std::unique_ptr<hermes::Buffer> data_;
    83  };
